const input = $input.first().json;
const LF = String.fromCharCode(10);
const DAY = 24 * 60 * 60 * 1000;
const store = $getWorkflowStaticData('global');
store.pendingMedia = store.pendingMedia || {};
store.pendingEdit = store.pendingEdit || {};
const now = Date.now();
for (const k of Object.keys(store.pendingMedia)) { if (now - store.pendingMedia[k].ts > DAY) delete store.pendingMedia[k]; }
for (const k of Object.keys(store.pendingEdit)) { if (now - store.pendingEdit[k].ts > DAY) delete store.pendingEdit[k]; }

let value = input;
if (!input.messages && Array.isArray(input.entry)) {
  const ch = ((input.entry[0] || {}).changes || [])[0] || {};
  value = ch.value || {};
}
const msg = (value.messages || [])[0];
const phoneNumberId = String((value.metadata || {}).phone_number_id || '');
if (!msg) return [{ json: { route: 'ignore', reason: 'no_message', phoneNumberId } }];

const digits = (s) => String(s || '').replace(/[^0-9]/g, '');
const from = digits(msg.from);
const allowed = String(input.allowedNumbers || '').split(',').map(digits).filter(Boolean);
if (!allowed.includes(from)) return [{ json: { route: 'ignore', reason: 'not_whitelisted', from, phoneNumberId } }];

function parsePrice(text) {
  if (!text) return null;
  const t = String(text).replace(/,/g, '');
  let m = t.match(/(?:₹|rs\.?|inr|price\s*[:=-]?)\s*(\d+(?:\.\d+)?)\s*(k)?/i);
  if (!m) m = t.match(/(\d+(?:\.\d+)?)\s*(k)?\b/i);
  if (!m) return null;
  let n = parseFloat(m[1]);
  if (m[2]) n = n * 1000;
  if (!isFinite(n) || n <= 0) return null;
  return n.toFixed(2);
}
const display = (p) => '₹' + Number(p).toLocaleString('en-IN', { maximumFractionDigits: 2 });
const base = { from, phoneNumberId };

const gql = (query, variables) => ({ query, variables });

function processItem(mediaId, caption, price) {
  return [{ json: { ...base, route: 'process', mediaId, caption: caption || '', price, priceDisplay: display(price),
    ackText: 'Got it! Rendering studio photos and writing SEO copy for ' + display(price) + '... I will send the Shopify draft here in a few minutes.' } }];
}

if (msg.type === 'image') {
  const mediaId = (msg.image || {}).id;
  const caption = (msg.image || {}).caption || '';
  const price = parsePrice(caption);
  if (price) return processItem(mediaId, caption, price);
  store.pendingMedia[from] = { mediaId, caption, ts: now };
  return [{ json: { ...base, route: 'reply', replyText: 'Photo received. Please reply with the price to continue (e.g. ₹1,499).' } }];
}

if (msg.type === 'interactive' || msg.type === 'button') {
  const id = msg.type === 'interactive'
    ? (((msg.interactive || {}).button_reply) || {}).id || ''
    : ((msg.button || {}).payload) || '';
  const parts = String(id).split('|');
  if (parts[0] === 'publish' && parts[1]) {
    const q = 'mutation productUpdate($product: ProductUpdateInput!) { productUpdate(product: $product) { product { id handle status onlineStoreUrl } userErrors { field message } } }';
    return [{ json: { ...base, route: 'publish', productId: parts[1], graphqlBody: gql(q, { product: { id: parts[1], status: 'ACTIVE' } }) } }];
  }
  if (parts[0] === 'edit' && parts[1] && parts[2]) {
    store.pendingEdit[from] = { productId: parts[1], variantId: parts[2], ts: now };
    return [{ json: { ...base, route: 'reply', replyText: 'Sure - reply with the new price (e.g. ₹1,299) and I will update the draft.' } }];
  }
  return [{ json: { ...base, route: 'ignore', reason: 'unknown_button' } }];
}

if (msg.type === 'text') {
  const body = ((msg.text || {}).body) || '';
  const price = parsePrice(body);
  const edit = store.pendingEdit[from];
  const media = store.pendingMedia[from];
  if (edit && price) {
    delete store.pendingEdit[from];
    const q = 'mutation productVariantsBulkUpdate($productId: ID!, $variants: [ProductVariantsBulkInput!]!) { productVariantsBulkUpdate(productId: $productId, variants: $variants) { productVariants { id price } userErrors { field message } } }';
    return [{ json: { ...base, route: 'update_price', price, priceDisplay: display(price),
      graphqlBody: gql(q, { productId: edit.productId, variants: [{ id: edit.variantId, price }] }) } }];
  }
  if (media && price) {
    delete store.pendingMedia[from];
    return processItem(media.mediaId, media.caption, price);
  }
  if (edit || media) {
    return [{ json: { ...base, route: 'reply', replyText: 'I could not read a price in that message. Please reply with just the price, e.g. ₹1,499.' } }];
  }
  return [{ json: { ...base, route: 'reply', replyText: ['Hi! To list a product:', '1. Send a product photo', '2. Put the price in the caption (e.g. ₹1,499)', '', 'I will create a Shopify draft with studio images and SEO copy.'].join(LF) } }];
}

return [{ json: { ...base, route: 'ignore', reason: 'unsupported_type_' + msg.type } }];

const out = $input.first().json.output || {};
const prompts = out.prompts || {};
const source = $('Download Product Image').first().binary || {};
const prefix = 'products/' + $execution.id + '-';
const shots = ['hero', 'lifestyle', 'detail'];
return shots.map((shot) => ({
  json: { shot, prompt: prompts[shot] || '', fileName: prefix + shot + '.png' },
  binary: source.data ? { data: source.data } : {},
}));

const item = $input.first().json;
const copy = item.output || {};
const msg = $('Parse Message').first().json;
const order = ['hero', 'lifestyle', 'detail'];
const images = (item.images || []).filter((i) => i && i.url).sort((a, b) => order.indexOf(a.shot) - order.indexOf(b.shot));
const alts = copy.alt_texts || {};
const files = images.map((img) => ({ originalSource: img.url, alt: alts[img.shot] || copy.title, contentType: 'IMAGE' }));
const input = {
  title: copy.title,
  handle: copy.handle,
  descriptionHtml: copy.body_html,
  tags: copy.tags || [],
  status: 'DRAFT',
  seo: { title: copy.seo_title, description: copy.seo_description },
  productOptions: [{ name: 'Title', values: [{ name: 'Default Title' }] }],
  variants: [{ optionValues: [{ optionName: 'Title', name: 'Default Title' }], price: msg.price }],
  files,
};
const query = 'mutation productSet($input: ProductSetInput!, $synchronous: Boolean!) { productSet(synchronous: $synchronous, input: $input) { product { id handle title status onlineStorePreviewUrl variants(first: 1) { nodes { id price } } } userErrors { field message } } }';
return [{ json: { graphqlBody: { query, variables: { input, synchronous: true } }, heroUrl: images.length ? images[0].url : '', title: copy.title } }];

const LF = String.fromCharCode(10);
const res = $input.first().json;
const ps = (res.data || {}).productSet || {};
const errors = (ps.userErrors || []).concat(res.errors || []);
if (!ps.product || (ps.userErrors || []).length) {
  throw new Error('Shopify productSet failed: ' + JSON.stringify(errors));
}
const product = ps.product;
const variant = ((product.variants || {}).nodes || [])[0] || {};
const msg = $('Parse Message').first().json;
const settings = $('Settings').first().json;
const payload = $('Build Shopify Payload').first().json;
const numericId = String(product.id).split('/').pop();
const adminUrl = 'https://admin.shopify.com/store/' + settings.shopSubdomain + '/products/' + numericId;
const previewUrl = product.onlineStorePreviewUrl || ('https://' + settings.shopSubdomain + '.myshopify.com/products/' + product.handle);
const bodyText = [
  '*' + product.title + '*',
  'Price: ' + msg.priceDisplay,
  'Status: Draft',
  '',
  'Admin: ' + adminUrl,
  'Preview: ' + previewUrl,
].join(LF).slice(0, 1024);
const interactive = {
  type: 'button',
  body: { text: bodyText },
  footer: { text: 'Tap to publish or change the price' },
  action: {
    buttons: [
      { type: 'reply', reply: { id: 'publish|' + product.id, title: 'Publish Live Now' } },
      { type: 'reply', reply: { id: 'edit|' + product.id + '|' + variant.id, title: 'Edit Price' } },
    ],
  },
};
if (payload.heroUrl) interactive.header = { type: 'image', image: { link: payload.heroUrl } };
return [{ json: {
  productId: product.id,
  adminUrl,
  previewUrl,
  whatsappBody: { messaging_product: 'whatsapp', recipient_type: 'individual', to: msg.from, type: 'interactive', interactive },
} }];
